L000444	\section{Numerical spin-1 simulations of soliton dynamics}\label{app:Numerics}
L000445	We are numerically simulating the spin-1 Gross-Pitaevskii equation (GPE), which in one spatial dimension is given by
L000446	\begin{align}
L000447	    \mathrm{i} \hbar \partial_t \boldsymbol{\psi}(x,t) &= \left[-\frac{\hbar^2}{2M}\partial_x^2+V(x)+qf_z^2 \right. \nonumber \\
L000448	    &+\left.\frac{c_0}{2}|\boldsymbol{\psi}(x,t)|^2+\frac{c_1}{2}\boldsymbol{F}(x,t)\boldsymbol{f} \right]\boldsymbol{\psi}(x,t),
L000449	\end{align}
L000450	where $\boldsymbol{f}$ is a vector containing the three spin matrices as defined in \cite{Kawaguchi2012}
L000451	\begin{equation}
L000452	    \boldsymbol{f} = (f_x,f_y,f_z)^T \, ,
L000453	\end{equation}
L000454	and the spin density $\boldsymbol{F}$(x,t) is given by
L000455	\begin{equation}
L000456	    \boldsymbol{F}=\begin{pmatrix}
L000457	        F_x \\
L000458	        F_y \\
L000459	        F_z
L000460	    \end{pmatrix}
L000461	    =
L000462	    \frac{1}{\sqrt{2}}
L000463	    \begin{pmatrix}
L000464	        \psi_0^*\left(\psi_{+1}+\psi_{-1}\right)+\mathrm{c.c.}\,\\
L000465	        \mathrm{i}\left[\psi_0^*\left(\psi_{+1}-\psi_{-1}\right)+\mathrm{c.c.}\,\right]\\
L000466	        \sqrt{2} \left(|\psi_{+1}|^2-|\psi_{-1}|^2\right)
L000467	    \end{pmatrix}.
L000468	    \label{eq:Spins}
L000469	\end{equation}
L000470	In the following, we want to numerically investigate effects that are due to the non-perfect experimental state preparation.
L000471	The state onto which the spinor phase imprint is made is chosen as either the ground state of the easy-plane ferromagnetic phase at $q=0$, that is
L000472	\begin{equation}
L000473	    \boldsymbol{\psi}_{\mathrm{EP}, q=0} = \frac{\sqrt{n}}{2}\begin{pmatrix}
L000474	        1 \\
L000475	        \sqrt{2} \\
L000476	        1
L000477	    \end{pmatrix} \:,
L000478	\end{equation}
L000479	corresponding to a fully elongated spin (this is similar to the experimental state preparation), or as the ground state of the easy-plane phase for the chosen $q$,
L000480	\begin{equation}
L000481	    \boldsymbol{\psi}_\mathrm{EP} = \frac{\sqrt{n}}{2}\begin{pmatrix}
L000482	        \sqrt{1-\frac{q}{2n|c_1|}}\\
L000483	         \sqrt{2(1+\frac{q}{2n|c_1|}}) \\
L000484	        \sqrt{1-\frac{q}{2n|c_1|}}
L000485	    \end{pmatrix} \:.
L000486	\end{equation}
L000487	If one does not use the appropriate ground state for a chosen $q$, the spin background of the system will undergo spin-length oscillations, as can be seen in Fig.~\ref{fig:simulation_kink_q03} for a moving soliton.
L000488	
L000489	\subsection{Experiment-like imprint}
L000490	To simulate a kink close to the experimental imprint the initial state is rotated in spin space with the generator of the rotation given by
L000491	\begin{equation}
L000492	    Q_0 = \begin{pmatrix}
L000493	        -1 & 0 & 0 \\
L000494	        0 & 1 & 0 \\
L000495	        0 & 0 & -1 \\
L000496	    \end{pmatrix} \:,
L000497	\end{equation}
L000498	with a position-dependent angle
L000499	\begin{equation}
L000500	    \varphi_\mathrm{rot}(x) = \begin{cases}\frac{\pi}{2} \exp(-\frac{\left(x-x_0\right)^2}{2\xi_\mathrm{s}^2}) \:,& \text{if } x\leq x_0 \:; \\
L000501	    \frac{\pi}{2} \:,& \text{if } x > x_0 \:.
L000502	    \end{cases}
L000503	    \label{eq:kink_simulation}
L000504	\end{equation}
L000505	This state preparation closely mimics the experimental imprint technique. The standard deviation of the Gaussian edge is chosen as the spin healing length
L000506	\begin{equation}
L000507	    \xi_\mathrm{s} = \frac{\hbar}{\sqrt{2Mn|c_1|}}\:,
L000508	\end{equation}
L000509	approximately corresponding to the size of the beam used in the experiment.
L000510	This leads to the initial state:
L000511	\begin{equation}
L000512	    \boldsymbol{\psi}_\mathrm{init}(x) = \boldsymbol{\psi}_\mathrm{EP}\cdot e^{-i\varphi_\mathrm{rot}(x)Q_0} \; .
L000513	\end{equation}
L000514	
L000515	How this compares to the analytical solution for kinks ($K$) and anti-kinks ($\overline{K}$) in the sine-Gordon model \cite{Cuevas-Maraver2014},
L000516	\begin{equation}
L000517	    \varphi_{S,\mathrm{K}/\overline{\mathrm{K}}} = 2\arctan\left[\exp\left(\pm \frac{x-x_0}{\ell}\right)\right]\: ,
L000518	    \label{eq:kink_analytics}
L000519	\end{equation}
L000520	is shown in Fig.~\ref{fig:simulation_spinorphase_slices}. In this analytical solution the width of the (anti-)kink $\ell$ is taken as
L000521	\begin{equation}
L000522	    \ell = \frac{1}{\sqrt{2}}\xi_\mathrm{s} = \frac{\hbar}{\sqrt{4Mn|c_1|}}\:,
L000523	\end{equation}
L000524	as given in \cite{Yu2021}.
L000525	To obtain the initial state from this phase, one adds $\phis$ as a  complex phase to the $m=0$ component:
L000526	\begin{equation}
L000527	    \boldsymbol{\psi}_\mathrm{init} = \begin{pmatrix}
L000528	        \psi_{\mathrm{EP},+1} \\
L000529	        \psi_{\mathrm{EP},0}\cdot e^{-\mathrm{i} \phis} \\
L000530	        \psi_{\mathrm{EP},-1}
L000531	    \end{pmatrix} \;.
L000532	\end{equation}
